// 1. Enter your sample and choose the number of bins.
values := []float64{2, 3, 3, 4, 4, 4, 5, 5, 5, 5, 6, 6, 6, 7, 7, 8, 8, 9, 10, 12}
bins := 6

// 3. Compare frequency and cumulative views.
hist := chartframe.New("Frequency").Labels("Value", "Count").Histogram("sample", values, bins)
cdf := chartframe.New("Empirical cumulative distribution").Labels("Value", "Proportion ≤ value").ECDF("sample", values)
err = chartframe.Grid("Distribution study", 1, hist, cdf).Save("distribution-study.svg")
if err != nil { panic(err) }
